/**
 * Turns a Verdict into allow / flag / deny.
 *
 * Shape of the decision, and why:
 *   - `deny` only on a near-certain single signal. TypeSafe publishes Jev
 *     accuracy below frontier models in several domains, so a hard block on a
 *     merely-probable signal produces false denials exactly where a gate is
 *     most wanted.
 *   - `flag` is the wide middle band, and it is a real tier now: it asks a
 *     human via $.ui.ask. A flag that resolves itself is not a gate.
 *   - low intent-consistency is its own flag trigger, independent of the
 *     probabilities, because "this is not what you said you were doing" is a
 *     different failure from "this looks dangerous".
 */

import type { Decision, ResolvedConfig, Verdict } from "./types";

export function decide(verdict: Verdict, config: ResolvedConfig): Decision {
  const reasons: string[] = [];
  let maxProbability = 0;

  for (const s of verdict.signals) {
    if (s.probability > maxProbability) maxProbability = s.probability;
    if (s.probability >= config.flagAbove) {
      reasons.push(`${s.label} (p=${s.probability.toFixed(2)})`);
    }
  }

  // Scores are zero-indexed: 0 is "contradicts", max is "fully consistent".
  const intent = verdict.intent;
  const lowIntent = intent !== null && intent.score <= config.lowIntentAtOrBelow;
  if (lowIntent) {
    reasons.push(
      `low consistency with the stated plan (${intent.score.toFixed(1)} of ${intent.max}, confidence ${intent.confidence.toFixed(2)})`
    );
  }

  if (maxProbability >= config.denyAbove) {
    return { action: "deny", reasons, maxProbability };
  }
  if (reasons.length > 0) {
    return { action: "flag", reasons, maxProbability };
  }
  return { action: "allow", reasons: [], maxProbability };
}

/** One line summarizing a decision, for the transcript and the audit log. */
export function summarize(tool: string, decision: Decision): string {
  if (decision.reasons.length === 0) {
    return `${tool}: no signal above threshold (max p=${decision.maxProbability.toFixed(2)})`;
  }
  return `${tool}: ${decision.reasons.join("; ")}`;
}

/**
 * What the agent is told when a call is blocked.
 *
 * Two different things block a call, and they are fixed with two different
 * settings. A block that came from nobody being able to answer must not send
 * the user to the thresholds: the thresholds were right, the question just
 * never reached a human. A human's own Block keeps the threshold wording —
 * there, the thresholds are why they were asked at all.
 */
export function denyMessage(tool: string, decision: Decision, askOutcome: string | null): string {
  const nobodyAsked =
    askOutcome === "non-interactive session" || (askOutcome !== null && askOutcome.startsWith("no answer:"));
  if (nobodyAsked) {
    return (
      `Blocked by stepwarden: ${summarize(tool, decision)} — a human had to decide and nobody could be asked ` +
      `(${askOutcome}). Run this in an interactive session to be asked, or set 'if nobody answers' to allow ` +
      "with /plugin configure stepwarden."
    );
  }
  return (
    `Blocked by stepwarden: ${summarize(tool, decision)}. ` +
    "If that is wrong, adjust the thresholds with /plugin configure stepwarden, or run /stepwarden to see the current policy."
  );
}

files.lib/redact.ts:
/**
 * Redaction + size-capping for anything that leaves the session.
 *
 * Two destinations make this necessary, and neither is obvious from the call
 * site: every verified tool call is (a) sent to TypeSafe's API and (b) written
 * to a local JSONL audit log. A `Bash` call can carry `AWS_SECRET=...` and a
 * `Write` call can carry an entire file body, so raw tool arguments must not
 * go out unfiltered — and a 2 MB file body would blow both the request latency
 * and the log.
 *
 * This is deliberately conservative pattern matching, not a secret scanner: it
 * catches the common shapes and truncates everything else. It reduces
 * exposure; it does not eliminate it, which is why the README says plainly
 * that tool arguments are sent to a third party.
 */

const MAX_STRING = 600;
const MAX_ARRAY = 20;
const MAX_DEPTH = 4;

/**
 * Terms that make a key's value a secret wherever they appear in the name.
 * These essentially never occur in a benign tool argument.
 */
const SECRET_SUBSTRINGS = [
  "secret",
  "password",
  "passwd",
  "credential",
  "apikey",
  "api_key",
  "api-key",
  "private_key",
  "privatekey",
  "access_token",
  "refresh_token",
  "auth_token",
  "bearer",
];

/**
 * Terms that are secrets only as the WHOLE key. Matching these as substrings
 * redacted ordinary arguments — `max_tokens` contains "token", `author`
 * contains "auth" — which both destroys the signal Jev needs and makes the
 * audit log unreadable.
 */
const SECRET_EXACT = new Set([
  "token",
  "auth",
  "authorization",
  "key",
  "cookie",
  "session_id",
  "sessionid",
  "pass",
  "credentials",
]);

function isSecretKey(name: string): boolean {
  const k = name.trim().toLowerCase();
  if (SECRET_EXACT.has(k)) return true;
  return SECRET_SUBSTRINGS.some((term) => k.includes(term));
}

/** Value shapes that look like credentials wherever they appear. */
const SECRET_VALUE: RegExp[] = [
  // KEY=value / KEY: value for a secret-ish name — a shell env assignment, and
  // the quoted "api_key": "..." form that appears in JSON bodies and configs.
  /(?:"|')?\b([A-Za-z0-9_]*(?:PASS(?:WD|WORD)?|SECRET|TOKEN|API[-_]?KEY|CREDENTIAL|PRIVATE[-_]?KEY)[A-Za-z0-9_]*)\b(?:"|')?\s*[=:]\s*("[^"]*"|'[^']*'|[^\s,;)}\]]+)/gi,
  // Common vendor key prefixes
  /\b((?:sk|pk|rk|apikey|ghp|gho|ghu|ghs|ghr|xox[baprs]|AKIA|ASIA)[-_][A-Za-z0-9_-]{8,})/g,
  /\b(AKIA[0-9A-Z]{16})\b/g,
  // Authorization headers
  /\b(Bearer|Basic)\s+([A-Za-z0-9._~+/=-]{12,})/gi,
  // PEM blocks
  /-----BEGIN[A-Z ]*PRIVATE KEY-----[\s\S]*?-----END[A-Z ]*PRIVATE KEY-----/g,
  // JWTs
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g,
];

export const REDACTED = "«redacted»";

/** Replaces credential-looking substrings inside a free-text value. */
export function redactString(input: string): string {
  let out = input;
  for (const re of SECRET_VALUE) {
    out = out.replace(re, (match: string, ...rest: unknown[]) => {
      const groups = rest.filter((g) => typeof g === "string") as string[];
      const name = groups[0];
      // Keep the name and the real separator so the shape stays readable (and
      // so a shell command is still parseable by Jev); replace only the value.
      if (name !== undefined) {
        const at = match.indexOf(name);
        const after = match.slice(at + name.length);
        const sep = after.match(/^["']?\s*[=:]\s*|^\s+/)?.[0];
        if (sep !== undefined) return `${match.slice(0, at + name.length)}${sep}${REDACTED}`;
      }
      return REDACTED;
    });
  }
  return out;
}

function truncate(s: string): string {
  return s.length <= MAX_STRING ? s : `${s.slice(0, MAX_STRING)}…[${s.length} chars]`;
}

function scrub(value: unknown, depth: number, keyHint?: string): unknown {
  if (keyHint && isSecretKey(keyHint)) return REDACTED;
  if (value === null || value === undefined) return value ?? null;

  const t = typeof value;
  if (t === "string") return truncate(redactString(value as string));
  if (t === "number" || t === "boolean") return value;
  if (t !== "object") return String(value);

  if (depth >= MAX_DEPTH) return "«depth»";

  if (Array.isArray(value)) {
    const head = value.slice(0, MAX_ARRAY).map((v) => scrub(v, depth + 1));
    return value.length > MAX_ARRAY ? [...head, `…[${value.length} items]`] : head;
  }

  // A null-prototype object so an argument named __proto__ is kept as data
  // rather than silently reassigning the result's prototype.
  const out = Object.create(null) as Record<string, unknown>;
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    out[k] = scrub(v, depth + 1, k);
  }
  return { ...out };
}

/**
 * The tool arguments as they may safely be sent to Jev and written to the
 * audit log: secrets masked, long values truncated, deep structures clipped.
 */
export function safeArgs(args: Record<string, unknown>): Record<string, unknown> {
  const scrubbed = scrub(args, 0);
  return scrubbed && typeof scrubbed === "object" && !Array.isArray(scrubbed)
    ? (scrubbed as Record<string, unknown>)
    : {};
}

/**
 * Splits a raw `tool.call` event into its identity and its arguments.
 *
 * A tool.call event is `{ tool, tool_use_id, ...the tool's own arguments }` —
 * the arguments are spread at the top level, there is no `input` wrapper.
 * These reserved keys are the engine's, not the tool's.
 */
const RESERVED = new Set(["tool", "tool_use_id", "agentId", "parentAgentId", "$shadowed"]);

export function splitEvent(e: Record<string, unknown>): {
  tool: string;
  toolUseId: string | undefined;
  args: Record<string, unknown>;
} {
  const args: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(e)) {
    if (!RESERVED.has(k)) args[k] = v;
  }
  return {
    tool: typeof e.tool === "string" ? e.tool : "(unknown)",
    toolUseId: typeof e.tool_use_id === "string" ? e.tool_use_id : undefined,
    args,
  };
}

files.lib/types.ts:
/**
 * Shared types.
 *
 * Everything in lib/ is PURE: no `$`, no imports other than relative ones.
 * That is not a style preference — the function-hooks loader refuses a module
 * that imports anything but a relative path or "claude-code", and its static
 * scanner refuses `$` crossing an import boundary. All engine access therefore
 * lives in hooks/verify.ts, and lib/ is plain data in, plain data out (which
 * also makes it directly unit-testable).
 */

/** What the policy decided, or what actually happened, for one tool call. */
export type Action = "allow" | "flag" | "deny";

/** How the plugin behaves overall. */
export type Mode = "enforce" | "audit" | "off";

/** One Jev signal, named for the audit log and the user-facing reason. */
export interface Signal {
  key: string;
  label: string;
  /** Calibrated probability 0..1 that the answer is "yes". */
  probability: number;
}

/** A parsed Jev verdict for one pending tool call. */
export interface Verdict {
  signals: Signal[];
  /**
   * Intent consistency on the supplied rubric. TypeSafe scores are indexed
   * FROM ZERO, so an N-entry rubric yields 0..N-1 — `max` is N-1, not N.
   */
  intent: { score: number; max: number; confidence: number } | null;
  usage: { inputTokens: number; outputTokens: number } | null;
  model: string | null;
}

export interface Decision {
  action: Action;
  reasons: string[];
  maxProbability: number;
}

/** A previous tool call, as fed back to Jev for contradiction checks. */
export interface HistoryEntry {
  tool: string;
  args: Record<string, unknown>;
  at: number;
}

export interface ResolvedConfig {
  mode: Mode;
  model: string;
  denyAbove: number;
  flagAbove: number;
  /** Intent score at or below this (0-indexed rubric) counts as a flag signal. */
  lowIntentAtOrBelow: number;
  /** Applied when Jev itself fails: the gate's own failure policy. */
  onError: Action;
  /** Applied to a flagged call when no human answer is available. */
  onNoAnswer: Action;
  /** Tools never sent to Jev at all (cheap, read-only, high-volume). */
  skipTools: string[];
  /** Milliseconds to wait for Jev before giving up and applying onError. */
  timeoutMs: number;
  /** Consecutive failures before the gate reports itself degraded. */
  unhealthyAfter: number;
  auditLog: boolean;
  /** Warnings raised while normalizing user input; surfaced at session start. */
  warnings: string[];
}

